// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testRegression_property() public {
        address revertingContract = address(new RevertingContract());

        bool ok;
        try c.forward(revertingContract, "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract RevertingContract {
    fallback() external payable {
        revert("always revert");
    }
}
